  var h=new HubState();h.reset(true);check(HubOverview.approval(h).contains("Loading")&&HubOverview.binding(h).contains("not confirmed"),"Loading never claims approval or binding");h.status=HubState.Status.READY;check(HubOverview.approval(h).equals("No character selected"),"Hub empty state is explicit");h.character="selected";h.characterApproved=true;check(HubOverview.approval(h).contains("approved")&&HubOverview.binding(h).contains("no character bound"),"Selected and approved does not imply bound");h.bound="other";check(HubOverview.binding(h).contains("another character"),"Another physical binding is distinguished from selection");h.bound=h.character;check(HubOverview.binding(h).equals("Your entity: character bound"),"Selected and physically bound status is explicit");h.campaign="campaign";h.manager=false;check(!h.dmTools(),"Non-DM tools disabled");h.manager=true;check(h.dmTools(),"Confirmed manager has tools");h.inCombat=true;check(!h.canSwitch()&&HubOverview.encounter(h).contains("locked"),"Encounter selection lock retained");h.reset(false);check(!h.dmTools()&&!h.canSwitch()&&!h.opensDashboard()&&HubOverview.approval(h).equals("Character unavailable"),"Unsupported server exposes no privileged action");
