  var artRoot=Path.of("src/main/resources/assets/tacticalcombat/textures/gui/hub");var atlas=ImageIO.read(artRoot.resolve("navigation-h.png").toFile());var manifest=JsonParser.parseString(Files.readString(artRoot.resolve("sprites.json"))).getAsJsonObject().getAsJsonObject("sprites");check(manifest.keySet().equals(HubIcons.KEYS)&&HubIcons.KEYS.size()==6,"Six new navigation symbols with no race/class role substitutions");for(String key:HubIcons.KEYS){var im=ImageIO.read(artRoot.resolve(key+".png").toFile());var bounds=manifest.getAsJsonObject(key).getAsJsonArray("sourceBounds");boolean gutter=true,exact=true;for(int y=0;y<516;y++)for(int x=0;x<516;x++){if(x<2||y<2||x>=514||y>=514)gutter&=(im.getRGB(x,y)>>>24)==0;else exact&=im.getRGB(x,y)==atlas.getRGB(bounds.get(0).getAsInt()+x-2,bounds.get(1).getAsInt()+y-2);}check(im.getWidth()==516&&im.getHeight()==516&&gutter&&exact,"Original navigation art packaged without resampling or clipping motif cells");check(Files.readString(artRoot.resolve(key+".png.mcmeta")).contains("\"blur\":false"),"Sharp nearest-neighbor texture metadata");}
